import type { Event, Manifest } from './types.ts';

export function summarize(manifest: Manifest, events: Event[]) {
  const rows = (['belief', 'question', 'adaptation'] as const).map(direction => {
    const cases = manifest.cases.filter(c => c.direction === direction);
    const attempts = events.filter(e => e.direction === direction);
    const canonical = attempts.filter(e => e.variant === 'canonical');
    const correct = (e: Event): boolean => e.response?.answers.judgment.type === 'choice' && manifest.gold[e.caseId].labels.includes(e.response.answers.judgment.choice);
    let changed = 0, comparisons = 0, harmful = 0;
    for (const event of attempts.filter(e => e.variant !== 'canonical')) {
      const base = canonical.find(e => e.caseId === event.caseId);
      const answer = event.response?.answers.judgment;
      const baseAnswer = base?.response?.answers.judgment;
      if (answer?.type !== 'choice' || baseAnswer?.type !== 'choice') continue;
      comparisons++;
      if (answer.choice !== baseAnswer.choice) {
        changed++;
        if (correct(base!) && !correct(event)) harmful++;
      }
    }
    return {
      direction, cases: cases.length,
      unaided: cases.filter(c => manifest.gold[c.id].labels.includes(manifest.baselines.unaided[c.id])).length,
      checklist: cases.filter(c => manifest.gold[c.id].labels.includes(manifest.baselines.checklist[c.id])).length,
      canonicalCorrect: canonical.filter(correct).length,
      canonicalValid: canonical.filter(e => !!e.response).length,
      allCorrect: attempts.filter(correct).length,
      allPlanned: cases.length * manifest.variants.length,
      failures: attempts.filter(e => !!e.error).length,
      changed, comparisons, harmful,
    };
  });
  const successes = events.filter(e => e.response);
  const sortedTimes = successes.map(e => e.elapsedMs).sort((a, b) => a - b);
  const medianMs = sortedTimes.length ? sortedTimes[Math.floor(sortedTimes.length / 2)] : null;
  return {
    rows,
    plannedRequests: manifest.plannedRequests,
    recordedRequests: events.length,
    successfulRequests: successes.length,
    failedRequests: events.filter(e => e.error).length,
    unattemptedRequests: manifest.plannedRequests - events.length,
    httpAttempts: events.reduce((n, e) => n + e.attempts, 0),
    inputTokens: successes.reduce((n, e) => n + e.response!.usage.input_tokens, 0),
    outputTokens: successes.reduce((n, e) => n + e.response!.usage.output_tokens, 0),
    reportedCostUsd: successes.some(e => e.response!.usage.cost !== undefined) ? successes.reduce((n, e) => n + (e.response!.usage.cost ?? 0), 0) : null,
    costCoverage: `${successes.filter(e => e.response!.usage.cost !== undefined).length}/${successes.length} validated responses; failed requests may have unrecorded charges`,
    medianMs,
    models: [...new Set(successes.map(e => e.response!.model))],
  };
}

/** Reports never count transport failures or unattempted cases as successful abstentions. */
export function renderReport(manifest: Manifest, events: Event[]): string {
  const summary = summarize(manifest, events);
  const lines = [
    `# Jev ${manifest.rubric.version}: ${manifest.split} ${manifest.live ? 'live run' : 'DRY RUN — NO INFERENCE'}`,
    '', `Created: ${manifest.createdAt}. Provider: ${manifest.provider}. Requested model: ${manifest.requestedModel}.`,
    `Returned models: ${summary.models.join(', ') || 'none'}.`, '',
    `Valid responses: ${summary.successfulRequests}/${summary.plannedRequests}. Failures: ${summary.failedRequests}. Unattempted: ${summary.unattemptedRequests}. HTTP attempts: ${summary.httpAttempts}.`,
    `Validated-response input/output tokens: ${summary.inputTokens}/${summary.outputTokens}. Reported cost: ${summary.reportedCostUsd === null ? 'unavailable' : '$' + summary.reportedCostUsd.toFixed(8)}. Cost coverage: ${summary.costCoverage}. Median successful request: ${summary.medianMs === null ? 'unavailable' : summary.medianMs.toFixed(0) + ' ms'}.`,
    '', '## Primary judgments', '',
    '| Direction | Same-author unaided | Same-author checklist | Jev canonical | Jev all variants | Errors | Label changes | Correct-to-wrong changes |',
    '| --- | --- | --- | --- | --- | --- | --- | --- |',
  ];
  for (const r of summary.rows) lines.push(`| ${r.direction} | ${r.unaided}/${r.cases} | ${r.checklist}/${r.cases} | ${manifest.live ? `${r.canonicalCorrect}/${r.cases}` : 'not run'} | ${manifest.live ? `${r.allCorrect}/${r.allPlanned}` : 'not run'} | ${r.failures} | ${r.changed}/${r.comparisons} | ${r.harmful} |`);
  lines.push('', 'Counts use predeclared acceptable labels. Equal acceptable alternatives can change labels harmlessly. Auxiliary scores and probabilities remain in events.jsonl; they have no measured accuracy claim or tuned automation threshold.', '',
    '## Case records', '', '| Case | Variant | Expected | Returned | Confidence | Result |', '| --- | --- | --- | --- | --- | --- |');
  for (const event of events) {
    const answer = event.response?.answers.judgment;
    const label = answer?.type === 'choice' ? answer.choice : 'none';
    const confidence = answer?.type === 'choice' ? answer.confidence.toFixed(3) : '—';
    const result = event.error ? `ERROR ${event.error.kind}${event.error.status ? ' ' + event.error.status : ''}` : manifest.gold[event.caseId].labels.includes(label) ? 'match' : 'MISMATCH';
    lines.push(`| ${event.caseId} | ${event.variant} | ${manifest.gold[event.caseId].labels.join(' or ')} | ${label} | ${confidence} | ${result} |`);
  }
  lines.push('', '## Limitations', '', manifest.baselines.limitation,
    '', 'The cases are short synthetic examples. Evaluation labels are reserved from rubric revision, but authored by the same agent. No blinding, calibration study, end-to-end host-agent trial, general truth verification, or formal value-function test is claimed. Development improvements and evaluation results must remain separate. Model scores cannot override constraints.',
    '', 'manifest.json freezes cases, labels, baseline answers, rubric, source hashes, and planned calls before inference. events.jsonl records exact requests, validated answers, redacted raw responses, latency, and failures. source-checks.json contains deterministic provenance checks.', '');
  return lines.join('\n');
}

src/runner.ts:
import { appendFile, mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { loadDataset } from './dataset.ts';
import { hash, readJson, root, writeJson } from './io.ts';
import { buildRequest, sourceChecks } from './questions.ts';
import { callProvider, defaultModels, endpoints } from './provider.ts';
import { renderReport, summarize } from './report.ts';
import type { Event, Manifest, Provider, Rubric, Split, Variant } from './types.ts';

export interface RunOptions {
  provider: Provider; split: Split; rubricVersion: 'v1' | 'v2'; variants: Variant[];
  live: boolean; apiKey?: string; model?: string; outputRoot?: string; maxRequests?: number;
  fetcher?: typeof fetch;
}

export async function runExperiment(options: RunOptions): Promise<string> {
  const rubric = await readJson<Rubric>(`${root}/experiments/rubrics/${options.rubricVersion}.json`);
  const data = await loadDataset(rubric);
  if (options.split === 'evaluation') {
    const revision = await readJson<{ revisedRubricHash: string; originalRubricHash: string; sourceRun: string; sourceManifestHash: string; sourceEventsHash: string }>(`${root}/experiments/revision.json`);
    const revised = await readJson<Rubric>(`${root}/experiments/rubrics/v2.json`);
    const original = await readJson<Rubric>(`${root}/experiments/rubrics/v1.json`);
    if (revision.revisedRubricHash !== hash(revised)) throw new Error('Revised rubric differs from its pre-evaluation freeze.');
    if (revision.originalRubricHash !== hash(original)) throw new Error('Original rubric differs from its pre-evaluation freeze.');
    const sourceManifest = await readJson<Manifest>(`${root}/${revision.sourceRun}/manifest.json`);
    const sourceEvents = await readFile(`${root}/${revision.sourceRun}/events.jsonl`, 'utf8');
    if (hash(sourceManifest) !== revision.sourceManifestHash || hash(sourceEvents) !== revision.sourceEventsHash) throw new Error('Revision source run has changed.');
    if (sourceManifest.hashes.cases !== hash(data.cases) || sourceManifest.hashes.gold !== hash(data.gold) || sourceManifest.hashes.baselines !== hash(data.baselines)) throw new Error('Cases, gold labels, or baselines changed after development. Start a new study.');
  }
  const cases = data.cases.filter(c => c.split === options.split);
  const plannedRequests = cases.length * options.variants.length;
  if (!options.variants.length || new Set(options.variants).size !== options.variants.length || !options.variants.includes('canonical')) throw new Error('Variants must be unique and include canonical.');
  if (plannedRequests > (options.maxRequests ?? 108)) throw new Error('Planned calls exceed the experiment request limit.');
  if (options.live && !options.apiKey) throw new Error(`Missing ${options.provider === 'typesafe' ? 'TYPESAFE_API_KEY' : 'OPENROUTER_API_KEY'} in the launching shell. No calls made.`);
  const runDir = join(options.outputRoot ?? `${root}/runs`, `${new Date().toISOString().replaceAll(':', '-')}-${options.rubricVersion}-${options.split}-${randomUUID().slice(0, 8)}`);
  await mkdir(runDir, { recursive: true });
  const codeFiles = (await readdir(`${root}/src`)).filter(f => f.endsWith('.ts')).sort();
  const sources = Object.fromEntries(await Promise.all(codeFiles.map(async f => [`src/${f}`, await readFile(`${root}/src/${f}`, 'utf8')])));
  const hashes = Object.fromEntries(Object.entries(sources).map(([path, source]) => [path, hash(source)]));
  const selectedGold = Object.fromEntries(cases.map(c => [c.id, data.gold[c.id]]));
  const manifest: Manifest = {
    schemaVersion: 1, createdAt: new Date().toISOString(), live: options.live,
    provider: options.provider, endpoint: endpoints[options.provider], requestedModel: options.model ?? defaultModels[options.provider],
    split: options.split, variants: options.variants, rubric, cases, gold: selectedGold, baselines: data.baselines,
    hashes: { ...hashes, cases: hash(data.cases), gold: hash(data.gold), baselines: hash(data.baselines), rubric: hash(rubric) }, plannedRequests,
  };
  await writeJson(join(runDir, 'manifest.json'), manifest);
  await writeJson(join(runDir, 'source-snapshot.json'), sources);
  await writeJson(join(runDir, 'source-checks.json'), Object.fromEntries(cases.map(c => [c.id, sourceChecks(c)])));
  // The request preview deliberately omits gold, baseline answers, and fixture titles.
  const requests = cases.flatMap(item => options.variants.map(variant => ({ item, variant, request: buildRequest(item, rubric, manifest.requestedModel, variant) })));
  await writeJson(join(runDir, 'requests.json'), requests.map(({ item, variant, request }) => ({ caseId: item.id, variant, request })));
  await writeFile(join(runDir, 'events.jsonl'), '', { flag: 'wx', mode: 0o600 });
  const events: Event[] = [];
  if (options.live) {
    for (const { item, variant, request } of requests) {
      const startedAt = new Date().toISOString(), start = performance.now();
      const result = await callProvider(options.provider, request, { apiKey: options.apiKey!, fetcher: options.fetcher });
      const event: Event = { caseId: item.id, direction: item.direction, variant, startedAt, request, fingerprint: hash(request), elapsedMs: performance.now() - start, ...result };
      // An interruption leaves all completed calls readable, never replaces an earlier run.
      await appendFile(join(runDir, 'events.jsonl'), JSON.stringify(event) + '\n');
      events.push(event);
      console.log(`${events.length}/${plannedRequests} ${item.id}/${variant}: ${event.error ? 'ERROR ' + event.error.kind : 'recorded'}`);
      if (event.error?.kind === 'configuration' || [401, 402, 403, 404].includes(event.error?.status ?? 0)) break;
    }
  }
  await writeJson(join(runDir, 'summary.json'), summarize(manifest, events));
  await writeFile(join(runDir, 'report.md'), renderReport(manifest, events), { flag: 'wx' });
  return runDir;
}

src/runtime-contracts.ts:
import { z } from 'zod';
import type { Answer, Question } from './types.ts';

export const identifier = z.string().regex(/^[a-zA-Z][a-zA-Z0-9_-]{0,63}$/).refine(s=>!['constructor','prototype','__proto__'].includes(s),'Reserved identifier').describe('Stable identifier, e.g. relevance or source_check.');
const prose = z.string().min(1).max(4000);
export const jsonValue = z.json().describe('JSON data. Use explicit fields and source references; never include API credentials.');
export const questionSchema = z.discriminatedUnion('type',[
  z.object({type:z.literal('noul').describe('Probability that a described condition holds.'),instructions:prose.describe('Complete yes/no judgment, e.g. Does item.text address context.query?'),criteria:z.object({true:prose.describe('Meaning of yes.'),false:prose.describe('Meaning of no.')}).strict().optional().describe('Optional explicit yes/no definitions.')}),
  z.object({type:z.literal('choice').describe('Select one of the supplied labels.'),instructions:prose.describe('Complete judgment to make from state.'),criteria:z.record(identifier,prose).refine(v=>Object.keys(v).length>=2&&Object.keys(v).length<=20,'Use 2–20 choice labels').describe('Labels and their meanings; include a no-match outcome when appropriate.')}),
  z.object({type:z.literal('score').describe('Expected position on ordered criteria.'),instructions:prose.describe('Independent dimension to rate.'),criteria:z.array(prose).min(2).max(8).describe('Ordered definitions from lowest to highest; resulting score ranges from 0 to length minus 1.')}),
]).describe('One typed Jev question. IDs are bookkeeping; put all meaning in instructions and criteria.');
export const questionsSchema = z.record(identifier,questionSchema).refine(v=>Object.keys(v).length>=1&&Object.keys(v).length<=16,'Use 1–16 questions').describe('Independent questions evaluated together over the same state.');
export const ruleSchema = z.object({
  stage:identifier.describe('Earlier stage whose answer supplies the value.'),
  question:identifier.describe('Question ID within that stage.'),
  op:z.enum(['eq','gte','lte']).describe('Exact label equality or numeric threshold comparison.'),
  value:z.union([z.string().max(100),z.number().finite()]).describe('Choice label, Noul threshold in [0,1], or Score threshold.'),
}).strict();
export const capabilitySchema = z.object({
  name:identifier.describe('Reusable capability name, e.g. research_relevance.'),
  description:prose.describe('Purpose, intended use, and practical limitations.'),
  stages:z.array(z.object({
    id:identifier.describe('Unique stage ID.'),
    questions:questionsSchema,
    when:z.array(ruleSchema).min(1).max(8).optional().describe('All conditions must pass. Missing/skipped/error answers do not pass.'),
  }).strict()).min(1).max(4).describe('Ordered stages. Each sees item, context, and prior stage answers. Later stages can depend on earlier results.'),
  select:z.array(ruleSchema).min(1).max(8).optional().describe('All conditions must pass to select an item; omitted means all successfully completed items.'),
  rank:z.object({stage:identifier,question:identifier,direction:z.enum(['asc','desc']).describe('Numeric sort direction; missing values sort last.')}).strict().optional().describe('Optional numeric ranking after all stages.'),
  notes:z.string().max(4000).optional().describe('Authored assumptions, provenance, or adaptation rationale; not evidence of effectiveness.'),
}).strict();
export type Capability = z.infer<typeof capabilitySchema>;
export type Rule = z.infer<typeof ruleSchema>;
export const itemSchema = z.object({id:identifier.describe('Unique stable item ID within a run.'),data:jsonValue}).strict();
export type WorkItem = z.infer<typeof itemSchema>;
export const recordSchema = z.object({
  id:identifier.describe('Stable record ID within its scope.'),
  scope:identifier.describe('Explicit collection or inquiry scope, e.g. skill_methods.'),
  title:z.string().min(1).max(240).describe('Short descriptive title.'),
  text:z.string().min(1).max(12000).describe('Original source passage or record text.'),
  source:z.string().min(1).max(2000).describe('Source URL, document reference, or observation identifier.'),
  kind:z.enum(['source','observation','hypothesis','method','plan','outcome']).describe('What the record represents; this role is preserved during retrieval.'),
  status:z.enum(['active','superseded','cancelled']).default('active').describe('Lifecycle gate; search returns active records only.'),
  metadata:jsonValue.optional().describe('Optional provenance, dates, dependencies, or imported database fields.'),
}).strict();
export type StoredRecord = z.infer<typeof recordSchema>;
export const referenceSchema = {name:identifier.describe('Saved capability name.'),version:z.number().int().positive().optional().describe('Exact version; omit to resolve latest once at the beginning of the call.')};
export const pageSchema = {limit:z.number().int().min(1).max(20).default(5).describe('Maximum results per page.'),cursor:z.string().max(3000).optional().describe('Opaque nextCursor from the same query; omit for first page.')};
export const runOptionsSchema = {
  maxCalls:z.number().int().min(1).max(64).default(32).describe('Hard preflight limit on potential model calls; each may retry once on transient HTTP errors.'),
  useCache:z.boolean().default(false).describe('Reuse successful identical requests for up to one hour; outputs clearly identify cache hits. Disable for fresh evaluation.'),
};

export class RuntimeError extends Error {
  code: string;
  constructor(code:string,message:string){super(message);this.code=code;}
}

/** Validate references and numeric domains before persisting or making network calls. */
export function validateCapability(value:unknown):Capability {
  const definition = capabilitySchema.parse(value), known = new Map<string,Record<string,Question>>();
  const check = (r:Rule, numericOnly=false) => {
    const q = known.get(r.stage)?.[r.question];
    if(!q) throw new RuntimeError('invalid_reference',`Unknown or forward answer reference: ${r.stage}.${r.question}.`);
    if(q.type==='choice') {
      if(numericOnly||r.op!=='eq'||typeof r.value!=='string'||!Object.hasOwn(q.criteria,r.value))throw new RuntimeError('invalid_rule','Choice rules must compare an existing label using eq.');
    } else {
      const high=q.type==='noul'?1:q.criteria.length-1;
      if(typeof r.value!=='number'||r.value<0||r.value>high)throw new RuntimeError('invalid_rule',`Numeric threshold must be between 0 and ${high}.`);
    }
  };
  for(const stage of definition.stages){
    if(known.has(stage.id))throw new RuntimeError('duplicate_stage',`Duplicate stage ${stage.id}.`);
    stage.when?.forEach(r=>check(r));known.set(stage.id,stage.questions);
  }
  definition.select?.forEach(r=>check(r));
  if(definition.rank)check({...definition.rank,op:'gte',value:0},true);
  return definition;
}
export function answerValue(answer?:Answer):string|number|undefined {
  return answer?.type==='choice'?answer.choice:answer?.type==='noul'?answer.noul:answer?.type==='score'?answer.score:undefined;
}
export function matches(rule:Rule,answers:Record<string,Record<string,Answer>>):boolean {
  const value=answerValue(answers[rule.stage]?.[rule.question]);
  if(value===undefined)return false;
  if(rule.op==='eq')return value===rule.value;
  return typeof value==='number'&&typeof rule.value==='number'&&(rule.op==='gte'?value>=rule.value:value<=rule.value);
}

